import {
    BadRequestException,
    ConflictException,
    forwardRef,
    Inject,
    Injectable,
    Logger,
    NotFoundException,
} from '@nestjs/common';
import {
    CreateMeasurementConfigDto,
    CreateMeasurementConfigurationResponse,
    measurementMode,
} from './dto/create-measurement-config.dto';
import { UpdateMeasurementConfigDto } from './dto/update-measurement-config.dto';
import { InfluxService } from '../influx/influx.service';
import {
    AgentAccessInformation,
    InfrastructureAccessInformation,
    MeasurementConfigEntity,
    SupportedAgentHostingPlatforms,
    SupportedResources,
} from './entities/measurement-config.entity';
import { v4 } from 'uuid';
import {
    ReadAllMeasurementConfigs,
    ReadMeasurementConfigDto,
    ReadMeasurementConfigResponse,
    ReadMeasurementResponseData,
} from './dto/read-measurement-config.dto';
import { SchedulerService } from '../scheduler/scheduler.service';
import { SchedulerStatus, schedulerType, SupportedMeasurementFrequencies } from '../scheduler/dto/scheduler.dto';
import {
    aggregationInterval,
    aggregationMethod,
    CreateDimensionDto,
    infrastructureType,
    roundingEnum,
    SampleType,
} from '../dimensions/dto/create-dimension.dto';
import { DimensionsService } from '../dimensions/dimensions.service';

@Injectable()
export class MeasurementConfigService {
    private static readonly logger = new Logger(MeasurementConfigService.name);

    constructor(
        readonly InfluxService: InfluxService,
        @Inject(forwardRef(() => SchedulerService)) readonly SchedulerService: SchedulerService,
        @Inject(forwardRef(() => DimensionsService)) readonly dimensionsService: DimensionsService
    ) {}

    async createMeasurementConfig(createDimensionDto: CreateDimensionDto, measurementId, businessID, dimensionId) {
        const {
            data: [{ measurementMode: argumentMeasurementMode, measurementConfiguration }],
        } = await this.findOne({ measurementId, businessID });
        this.validateIntelligentMeasurement(createDimensionDto, argumentMeasurementMode, measurementConfiguration);
        const { transformDtoToEntityInput } = this.dimensionsService;
        const entity = transformDtoToEntityInput(
            {
                ...createDimensionDto,
                businessID,
            },
            dimensionId
        );
        return entity;
    }

    async create(
        createMeasurementConfigDto: CreateMeasurementConfigDto,
        subject
    ): Promise<CreateMeasurementConfigurationResponse> {
        MeasurementConfigService.logger.log(
            'Creating Measurement Config with the following inputs',
            createMeasurementConfigDto
        );
        const {
            businessID,
            measurementMode: chosenMeasurementMode,
            measurementConfiguration,
            measurementName,
        } = createMeasurementConfigDto;

        const { loadPoints } = this.InfluxService;
        const measurementId = v4();

        const measurementConfigEntity = new MeasurementConfigEntity({
            measurementId,
            measurementMode: chosenMeasurementMode,
            measurementConfiguration,
            businessID,
            subject,
            measurementName,
        });
        const dbModel = MeasurementConfigEntity.transformer(measurementConfigEntity, this.InfluxService);
        await MeasurementConfigEntity.setupAccessIfRequired(measurementConfigEntity);
        await loadPoints(`${process.env.STAGE}-config`, 'paigo', dbModel);
        MeasurementConfigService.logger.log('Loaded information into DB');

        return { message: 'Created Measurement Configuration', measurementId };
    }

    async findAll({ businessID }: ReadAllMeasurementConfigs): Promise<ReadMeasurementConfigResponse> {
        MeasurementConfigService.logger.log(`Reading all measurements for businessID: ${businessID}`);
        const { readAllMeaurements } = this.InfluxService;
        const dbModels = await readAllMeaurements({ businessID });
        if (dbModels.length === 0) {
            return { message: 'No Measurements Found', data: [] };
        }

        const entities = dbModels.map((dbModel) => MeasurementConfigEntity.dbModelToEntity(dbModel));
        const filtered = entities.filter((e) => e);
        return ReadMeasurementConfigResponse.entityToReadResponse(filtered);
    }

    async findOne({ measurementId, businessID }: ReadMeasurementConfigDto) {
        MeasurementConfigService.logger.log('Reading Measurement for the following ID', measurementId);
        const { readMeasurementConfigData } = this.InfluxService;
        const dbModels = await readMeasurementConfigData({ measurementId, businessID });

        MeasurementConfigService.logger.log('Response from Influx for MeasurementConfig', JSON.stringify(dbModels));

        if (dbModels.length === 0) {
            throw new NotFoundException(`No Measurement Configuration found for ID: ${measurementId}`);
        }

        const entities = dbModels.map((dbModel) => MeasurementConfigEntity.dbModelToEntity(dbModel));

        return ReadMeasurementConfigResponse.entityToReadResponse(entities);
    }

    async update(
        {
            measurementId,
            businessID,
            measurementName: updatedMeasurementName,
            ...restOfUpdate
        }: UpdateMeasurementConfigDto,
        subject
    ): Promise<CreateMeasurementConfigurationResponse> {
        MeasurementConfigService.logger.log('Updating Measurement Config', {
            measurementId,
        });

        const {
            data: [createMeasurementConfigDto],
        } = await this.findOne({ measurementId, businessID });

        const {
            measurementMode: chosenMeasurementMode,
            measurementConfiguration: { ...rest },
            measurementName,
        } = createMeasurementConfigDto;
        if (
            restOfUpdate.measurementMode &&
            restOfUpdate.measurementMode.toLowerCase() !== chosenMeasurementMode.toLowerCase()
        ) {
            throw new BadRequestException(
                'Cannot Update Measurement Mode please create a new measurement and delete this one if you want to change the measurement mode'
            );
        }

        const { loadPoints } = this.InfluxService;

        const measurementConfigEntity = new MeasurementConfigEntity({
            measurementId,
            measurementMode: chosenMeasurementMode,
            measurementConfiguration: { ...rest, ...restOfUpdate?.measurementConfiguration },
            businessID,
            subject,
            measurementName: updatedMeasurementName ? updatedMeasurementName : measurementName,
        });
        const dbModel = MeasurementConfigEntity.transformer(measurementConfigEntity, this.InfluxService);
        await loadPoints(`${process.env.STAGE}-config`, 'paigo', dbModel);
        return { measurementId, message: 'Updated Measurement Configuration' };
    }

    async remove({ measurementId, businessID }) {
        MeasurementConfigService.logger.log(
            `Attempting to delete measurement config: ${measurementId} for ${businessID}`
        );
        const measurementDbModels = await this.InfluxService.readMeasurementConfigData({ businessID, measurementId });
        if (measurementDbModels.length) {
            const { loadPoints } = this.InfluxService;
            // Check to see if any active dimension has the measurement attached
            const dimensionIds = await this.dimensionsService.findByMeasurementId({ businessID, measurementId });
            if (dimensionIds.length) {
                throw new ConflictException(
                    `Measurement is currently attached to dimensions ${dimensionIds.reduce((acc, item) => {
                        acc += `  DimensionId: ${item}  `;
                        return acc;
                    }, '')}`
                );
            }
            const entity = MeasurementConfigEntity.dbModelToEntity(measurementDbModels[0]);
            entity.softDelete = true;
            entity.businessID = businessID;
            const points = MeasurementConfigEntity.transformer(entity, this.InfluxService);
            MeasurementConfigService.logger.log('Points to delete', points);

            await loadPoints(`${process.env.STAGE}-config`, `paigo`, points);

            return { message: 'Deleted Measurement Config', measurementId: entity.measurementId };
        } else {
            throw new NotFoundException(`No Measurement configurations matching ID measurementId:${measurementId}`);
        }
    }

    private validateIntelligentMeasurement(dimension: CreateDimensionDto, mode: measurementMode, configuration): void {
        MeasurementConfigService.logger.log('Validating Intelligent Measurement: ', { dimension, mode, configuration });
        const {
            consumptionUnit: dimensionConsumptionUnit,
            usageIncrement: dimensionUsageIncrement,
            rounding: dimensionRounding,
            sampleType: dimensionSampleType,
            aggregationInterval: dimensionAggregationInterval,
            aggregationMethod: dimensionAggregationMethod,
        } = dimension;
        if (mode === measurementMode.infrastructureBased && configuration instanceof InfrastructureAccessInformation) {
            if (
                configuration.resourceType === SupportedResources.ebs ||
                configuration.resourceType === SupportedResources.ebssnapshot
            ) {
                if (dimensionConsumptionUnit?.type?.toLocaleLowerCase() !== 'data') {
                    throw new BadRequestException(
                        'Consumption Unit for EBS Volume and Snapshot Measurement must be Data type'
                    );
                }
                if (dimensionConsumptionUnit?.unit?.toLocaleLowerCase() !== 'gigabyte') {
                    throw new BadRequestException(
                        'Consumption Unit for EBS Volume and Snapshot Measurement must be gigabyte'
                    );
                }
                if (dimensionUsageIncrement !== 1) {
                    throw new BadRequestException('Usage Increment for EBS Volume and Snapshot Measurement must be 1');
                }
                if (dimensionRounding !== roundingEnum.ceiling) {
                    throw new BadRequestException('Rounding for EBS Volume and Snapshot Measurement must be Ceiling');
                }
                if (dimensionSampleType !== SampleType.gauge) {
                    throw new BadRequestException('Sample Type for EBS Volume and Snapshot Measurement must be Gauge');
                }
                if (dimensionAggregationInterval !== aggregationInterval.hour) {
                    throw new BadRequestException(
                        'Aggregation Interval for EBS Volume and Snapshot Measurement must be Hour'
                    );
                }
                if (dimensionAggregationMethod !== aggregationMethod.max) {
                    throw new BadRequestException(
                        'Aggregation Method for EBS Volume and Snapshot Measurement must be Max'
                    );
                }
            } else if (configuration.resourceType === SupportedResources.ec2Egress) {
                if (dimensionConsumptionUnit?.type?.toLocaleLowerCase() !== 'data') {
                    throw new BadRequestException('Consumption Unit for EC2 Egress must be Data type');
                }
                if (dimensionConsumptionUnit?.unit?.toLocaleLowerCase() !== 'byte') {
                    throw new BadRequestException('Consumption Unit for EC2 Egress Measurement must be byte');
                }
                if (dimensionUsageIncrement !== 1) {
                    throw new BadRequestException('Usage Increment for EC2 Egress Measurement must be 1');
                }
                if (dimensionRounding !== roundingEnum.ceiling) {
                    throw new BadRequestException('Rounding for EC2 Egress Measurement must be Ceiling');
                }
                if (dimensionSampleType !== SampleType.gauge) {
                    throw new BadRequestException('Sample Type for EC2 Egress Measurement must be Gauge');
                }
                if (dimensionAggregationInterval !== aggregationInterval.hour) {
                    throw new BadRequestException('Aggregation Interval for EC2 Egress Measurement must be Hour');
                }
                if (dimensionAggregationMethod !== aggregationMethod.sum) {
                    throw new BadRequestException('Aggregation Method for EC2 Egress Measurement must be Max');
                }
            } else if (configuration.resourceType === SupportedResources.ec2) {
                if (dimensionConsumptionUnit?.type?.toLocaleLowerCase() !== 'time') {
                    throw new BadRequestException(
                        'Consumption Unit for EC2 Running Time Measurement must be Time type'
                    );
                }
                if (dimensionConsumptionUnit?.unit?.toLocaleLowerCase() !== 'hour') {
                    throw new BadRequestException('Consumption Unit for EC2 Running Time Measurement must be Hour');
                }
                if (dimensionUsageIncrement !== 1) {
                    throw new BadRequestException('Usage Increment for EC2 Running Time Measurement must be 1');
                }
                if (dimensionRounding !== roundingEnum.ceiling) {
                    throw new BadRequestException('Rounding for EC2 Running Time Measurement must be Ceiling');
                }
                if (dimensionSampleType !== SampleType.gauge) {
                    throw new BadRequestException('Sample Type for EC2 Running Time Measurement must be Gauge');
                }
                if (dimensionAggregationInterval !== aggregationInterval.hour) {
                    throw new BadRequestException('Aggregation Interval for EC2 Running Time Measurement must be Hour');
                }
                if (dimensionAggregationMethod !== aggregationMethod.sum) {
                    throw new BadRequestException('Aggregation Method for EC2 Running Time Measurement must be Sum');
                }
            }
        } else if (mode === measurementMode.agentBased && configuration instanceof AgentAccessInformation) {
            if (configuration.hostingPlatform === SupportedAgentHostingPlatforms.eks) {
                if (dimensionConsumptionUnit?.type?.toLocaleLowerCase() !== 'time') {
                    throw new BadRequestException(
                        'Consumption Unit for EKS pod running time Measurement must be Time type'
                    );
                }
                if (dimensionConsumptionUnit?.unit?.toLocaleLowerCase() !== 'hour') {
                    throw new BadRequestException('Consumption Unit for EKS pod running time Measurement must be Hour');
                }
                if (dimensionUsageIncrement !== 1) {
                    throw new BadRequestException('Usage Increment for EKS pod running time Measurement must be 1');
                }
                if (dimensionRounding !== roundingEnum.ceiling) {
                    throw new BadRequestException('Rounding for EKS pod running time Measurement must be Ceiling');
                }
                if (dimensionSampleType !== SampleType.gauge) {
                    throw new BadRequestException('Sample Type for EKS pod running time Measurement must be Gauge');
                }
                if (dimensionAggregationInterval !== aggregationInterval.hour) {
                    throw new BadRequestException(
                        'Aggregation Interval for EKS pod running time Measurement must be Hour'
                    );
                }
                if (dimensionAggregationMethod !== aggregationMethod.sum) {
                    throw new BadRequestException(
                        'Aggregation Method for EKS pod running time Measurement must be Sum'
                    );
                }
            }
        } else {
            throw new BadRequestException(
                `Invalid Measurement Mode and Configurations combination. Mode: ${mode}, Configurations: ${configuration}`
            );
        }
    }

    /**
     * A method to compare a measurement to the stored measurements in DB.
     * Initally this is needed to make sure that duplicate measurements don't get added
     *
     * @returns true when a measurement equals a measurement found in the DB
     * @returns false when there is no measurement found.
     */
    private measurementComparision(
        argumentMeasurement: CreateMeasurementConfigDto,
        foundMeasurements: ReadMeasurementResponseData[]
    ): boolean {
        const storedCreatedMeasurements = foundMeasurements.map(
            ({ measurementId, ...rest }): CreateMeasurementConfigDto => rest
        );
        const results = foundMeasurements.filter(
            ({ measurementMode }) => argumentMeasurement['measurementMode'] === measurementMode
        );
        if (results.length) {
            return true;
        } else {
            return false;
        }
    }
}

import { Point } from '@influxdata/influxdb-client';
import { BadRequestException, InternalServerErrorException } from '@nestjs/common';
import { ApiHideProperty, ApiProperty } from '@nestjs/swagger';
import { IsArray, IsEnum, IsNotEmpty, IsOptional, IsString, Matches, Validate } from 'class-validator';
import { aggregationType } from '../../dimensions/entities/dimensions.entity';

import { InfluxService } from '../../influx/influx.service';
import { CreateUserDto } from '../../users/dto/create-user.dto';
import { measurementMode } from '../dto/create-measurement-config.dto';
import { ReadMeasurementResponseData } from '../dto/read-measurement-config.dto';
import { ValidIAMRole } from '../../setting/dto/customIAMAuthorizer';
import { S3 } from '@aws-sdk/client-s3';

/**
 * @author Daniel Wasserlauf <daniel.wasserlauf@paigo.tech>
 *
 * @enum The list of supported cloud platforms
 * @example "AWS"
 */
export enum supportedCloudPlatforms {
    aws = 'aws',
}
export enum SupportedResources {
    ebssnapshot = 'ebssnapshot',
    ebs = 'ebs',
    k8sPod = 'k8spod',
    ec2 = 'ec2',
    ec2Egress = 'ec2egress',
    /**
     * For internal use only
     */
    usageData = 'usageData',
}
export enum SupportedAgentHostingPlatforms {
    eks = 'k8spod',
}

export const supportedResourceHostingPlatformAggregationTypeMap = {
    [SupportedResources.k8sPod]: aggregationType.podUptime,
    [SupportedResources.ebs]: aggregationType.ebsVolume,
    [SupportedResources.ec2]: aggregationType.standard,
    [SupportedResources.ec2Egress]: aggregationType.standard,
    [SupportedResources.ebssnapshot]: aggregationType.ebsSnapshot,
    [SupportedAgentHostingPlatforms.eks]: aggregationType.podUptime,
};

export class IAMAccessCredentials {
    /**
     * The IAM role created by SaaS business and can be by Paigo AWS account to measure usage.
     * <br><br>
     * Example "arn:aws:iam::214826386939:role/paigo-scraper"
     */
    @ValidIAMRole('externalId', {
        message: 'Unable to authenticate with the IAM role and External ID provided. Please double check',
    })
    @IsNotEmpty()
    @ApiProperty()
    public iamRoleArn: string;

    /**
     * The Optional ExternalID associated with the IAM role.
     */
    @IsString()
    @IsOptional()
    @ApiProperty()
    public externalId?: string;

    constructor(access) {
        if (access) {
            const { iamRoleArn, externalId } = access;
            this.externalId = externalId;
            this.iamRoleArn = iamRoleArn;
        }
    }
}

/**
 * @author Daniel Wasserlauf <daniel.wasserlauf@paigo.tech>
 *
 * @enum The list of Supported AWS resources
 * @example "EBS"
 */

export class MeasurementConfigEntity {
    @ApiHideProperty()
    public static _measurement = 'MeasurementConfiguration';

    /**
     * The measurement method.
     * See <a href="https://docs.paigo.tech/measure-usage-and-collect-data/measure-and-collect-usage-data-at-production-scale">Measure and Collect Usage Data at Production Scale</a> for more information.
     * <br><br>
     * Example `"agentBased"`
     */
    public measurementMode: measurementMode;

    /**
     * Unique identifier assigned by Paigo.
     * <br><br>
     * Example `"de388932-a7e1-11ed-afa1-0242ac120002"`
     */
    @ApiProperty()
    public measurementId: string;

    /**
     * Configurations of the measurement
     */
    public measurementConfiguration:
        | InfrastructureAccessInformation
        | AgentAccessInformation
        | DatastoreAccessInformation;

    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public businessID?: string;

    /**
     * The subject associated with the user
     */
    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public subject: CreateUserDto['subject'];

    /**
     * The value indicating if a measurement configuration is soft deleted
     * */
    @ApiHideProperty()
    public softDelete?: boolean;

    public measurementName: string;
    constructor({
        measurementMode: argumentMeasurementMode,
        measurementConfiguration,
        measurementId,
        businessID,
        measurementName,
        subject,
    }: MeasurementConfigEntity) {
        this.measurementMode = argumentMeasurementMode;
        if (argumentMeasurementMode.toLowerCase() === measurementMode.infrastructureBased.toLowerCase()) {
            this.measurementConfiguration = new InfrastructureAccessInformation(
                measurementConfiguration as InfrastructureAccessInformation
            );
        } else if (argumentMeasurementMode.toLowerCase() === measurementMode.agentBased.toLowerCase()) {
            this.measurementConfiguration = new AgentAccessInformation(
                measurementConfiguration as AgentAccessInformation
            );
        } else if (argumentMeasurementMode.toLowerCase() === measurementMode.datastoreBased.toLowerCase()) {
            this.measurementConfiguration = new DatastoreAccessInformation({
                ...measurementConfiguration,
                businessID,
            } as DatastoreAccessInformation);
        }
        this.measurementId = measurementId;
        this.businessID = businessID;
        this.subject = subject;
        this.measurementName = measurementName;
    }

    static transformer(measurementConfigEntity: MeasurementConfigEntity, influxService: InfluxService): Array<Point> {
        const measurementConfigEntityPoint = influxService.getPoint(MeasurementConfigEntity._measurement);
        const {
            measurementMode: argumentMeasurementMode,
            measurementConfiguration,
            measurementId,
            businessID,
            subject,
            softDelete,
            measurementName,
        } = measurementConfigEntity;

        measurementConfigEntityPoint.stringField('measurementMode', argumentMeasurementMode);
        measurementConfigEntityPoint.tag('measurementId', measurementId);

        measurementConfigEntityPoint.tag('businessID', businessID);
        measurementConfigEntityPoint.tag('subject', subject);
        measurementConfigEntityPoint.tag('measurementName', measurementName);
        if (softDelete) {
            measurementConfigEntityPoint.tag('softDelete', 'deleted');
        }
        if (argumentMeasurementMode.toLowerCase() === measurementMode.infrastructureBased.toLowerCase()) {
            const completedPoint = InfrastructureAccessInformation.transformer(
                measurementConfiguration as InfrastructureAccessInformation,
                measurementConfigEntityPoint
            );

            return [completedPoint];
        } else if (argumentMeasurementMode.toLowerCase() === measurementMode.agentBased.toLowerCase()) {
            const completedPoint = AgentAccessInformation.transformer(
                measurementConfiguration as AgentAccessInformation,
                measurementConfigEntityPoint
            );

            return [completedPoint];
        } else if (argumentMeasurementMode.toLowerCase() === measurementMode.datastoreBased.toLowerCase()) {
            console.log('DB  transformer', measurementConfiguration);
            const completedPoint = DatastoreAccessInformation.transformer(
                measurementConfiguration as DatastoreAccessInformation,
                measurementConfigEntityPoint
            );

            return [completedPoint];
        } else {
            throw new InternalServerErrorException('Failed to Create Entity and store Measurmenent in DB');
        }
    }
    static dbModelToEntity({
        measurementId,
        _value,
        businessID,
        measurementName,
        subject,
        ...rest
    }: {
        [x: string]: any;
    }) {
        if (_value && _value.toLowerCase() === measurementMode.infrastructureBased.toLowerCase()) {
            const infrastructureAccessInformation = InfrastructureAccessInformation.dbModelToEntity({ ...rest });

            return new MeasurementConfigEntity({
                measurementId,
                measurementMode: _value,
                businessID,
                measurementConfiguration: infrastructureAccessInformation,
                subject,
                measurementName,
            });
        } else if (_value && _value.toLowerCase() === measurementMode.agentBased.toLowerCase()) {
            const agentAccessInformation = AgentAccessInformation.dbModelToEntity({
                ...rest,
            });
            return new MeasurementConfigEntity({
                measurementId,
                measurementMode: _value,
                businessID,
                measurementConfiguration: agentAccessInformation,
                subject,
                measurementName,
            });
        } else if (_value && _value.toLowerCase() === measurementMode.datastoreBased.toLowerCase()) {
            const dbAccessInformation = DatastoreAccessInformation.dbModelToEntity({
                ...rest,
            });
            return new MeasurementConfigEntity({
                measurementId,
                measurementMode: _value,
                businessID,
                measurementConfiguration: dbAccessInformation,
                subject,
                measurementName,
            });
        }
    }

    static determineAggregationTypeForMeasurement({
        measurementConfiguration: measurementConfig,
    }: MeasurementConfigEntity | ReadMeasurementResponseData) {
        if (measurementConfig instanceof InfrastructureAccessInformation) {
            return supportedResourceHostingPlatformAggregationTypeMap[measurementConfig.resourceType];
        } else if (measurementConfig instanceof AgentAccessInformation) {
            return supportedResourceHostingPlatformAggregationTypeMap[measurementConfig.hostingPlatform];
        } else {
            throw new InternalServerErrorException('Couldnt create Aggregation Schedule for Dimension');
        }
    }
    static async setupAccessIfRequired(measurementConfig: MeasurementConfigEntity) {
        if (measurementConfig.measurementMode.toLowerCase() === measurementMode.datastoreBased.toLowerCase()) {
            console.log('setting up access');
            return DatastoreAccessInformation.setupAccess(
                measurementConfig.measurementConfiguration as DatastoreAccessInformation
            );
        } else {
            return Promise.resolve();
        }
    }
}

export class PaigoFilters {
    /**
     *
     * The string containing the key associated with a metadata tag.
     * This could be an tag on AWS infrastructure, or a label on a kubernetes pod
     */
    @IsString()
    @IsNotEmpty()
    public key: string;
    /**
     *
     * The string containing the value associated with a metadata tag.
     * This could be an tag on AWS infrastructure, or a label on a kubernetes pod
     */
    @IsArray()
    @IsNotEmpty()
    public values: Array<string>;
}
export class InfrastructureAccessInformation extends IAMAccessCredentials {
    /**
     * Cloud infrastructure platform
     */
    @Matches(
        `^${Object.values(supportedCloudPlatforms)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsNotEmpty()
    @ApiProperty({ enum: supportedCloudPlatforms, isArray: false, example: 'aws' })
    public cloudPlatform: supportedCloudPlatforms;

    /**
     *
     * Supported region of the infrastructure
     *
     * Example `"us-east-1"`
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty()
    public region: string;

    /**
     * Underlying resource type which Paigo measures usage for.
     *
     */
    @Matches(
        `^${Object.values(SupportedResources)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @ApiProperty({
        enum: SupportedResources,
        isArray: false,
    })
    public resourceType: SupportedResources;

    constructor(accessInfo) {
        super({ ...accessInfo });
        if (accessInfo) {
            const { cloudPlatform, region, resourceType } = accessInfo;
            this.cloudPlatform = cloudPlatform;

            this.region = region;
            this.resourceType = resourceType;
        }
    }
    public static transformer(
        infrastructureAccessInformation: InfrastructureAccessInformation,
        influxPoint: Point
    ): Point {
        if (infrastructureAccessInformation) {
            const { iamRoleArn, externalId } = infrastructureAccessInformation;

            influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) {
                influxPoint.tag('externalId', externalId);
            }

            influxPoint.tag('cloudPlatform', infrastructureAccessInformation.cloudPlatform.toLowerCase());
            influxPoint.tag('region', infrastructureAccessInformation.region);
            if (infrastructureAccessInformation.resourceType) {
                influxPoint.tag('resourceType', infrastructureAccessInformation.resourceType.toLowerCase());
            }

            return influxPoint;
        }
    }

    public static dbModelToEntity({
        cloudPlatform,
        region,
        resourceType,
        iamRoleArn,
        externalId = '',
    }: {
        [x: string]: any;
    }) {
        return new InfrastructureAccessInformation({
            cloudPlatform: cloudPlatform.toLowerCase(),
            region,
            resourceType: resourceType,
            iamRoleArn,
            externalId,
        });
    }
}
export enum SupportedDatastores {
    s3 = 's3',
}
/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors inside of Confluent Cloud to pull data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a Kinesis Connector
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying resource type which paigo connects to. Default is s3.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public datastoreType?: SupportedDatastores;

    /**
     *
     * Whether paigo is hosting the ingestion endpoint, or it is hosted by the client. Optional, default is `true`.
     * @example 'true'
     */
    @IsString()
    @IsOptional()
    public paigoHosted?: 'true';

    /**
     *
     * What is the cloud environment associated with the ingestion endpoint. Optional, default is `aws`.
     * @example "aws"
     */
    @IsEnum(supportedCloudPlatforms)
    @IsOptional()
    public hostedCloud?: supportedCloudPlatforms;

    /**
     * The Unqiue ID for the cloud env where the resource is hosted. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    public cloudId: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const { cloudId, hostedCloud, paigoHosted, datastoreType, businessID } = datastoreAccessInformation;
            this.cloudId = cloudId;
            this.hostedCloud = hostedCloud ? hostedCloud : supportedCloudPlatforms.aws;
            this.paigoHosted = paigoHosted ? paigoHosted : 'true';
            this.datastoreType = datastoreType ? datastoreType : SupportedDatastores.s3;
            this.businessID = businessID;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { datastoreType: supportedDbs, paigoHosted, hostedCloud, cloudId } = datastoreAccessInformation;
            if (supportedDbs) influxPoint.tag('supportedDbs', supportedDbs);
            if (paigoHosted) influxPoint.tag('paigoHosted', paigoHosted);
            if (hostedCloud) influxPoint.tag('hostedCloud', hostedCloud);
            if (cloudId) influxPoint.tag('cloudId', cloudId);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        datastoreType,
        paigoHosted,
        hostedCloud,
        cloudId,
        businessID,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            datastoreType,
            paigoHosted,
            hostedCloud,
            cloudId,
            businessID,
        });
    }
    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { paigoHosted, cloudId, datastoreType, businessID } = dbAccessInformation;

        if (paigoHosted && datastoreType === SupportedDatastores.s3) {
            try {
                // Add the cloudId as a root account on the policy of the S3 bucket, two hardcoded buckets for now: paigo-usage-record-dlq-bucket and paigo-usage-record-dump-bucket

                // Get the current policy of the bucket
                const s3 = new S3({});
                const params = {
                    Bucket: `${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
                };
                const policy = await s3.getBucketPolicy(params);
                const policyJson = JSON.parse(policy.Policy);
                const statement = policyJson.Statement;
                const rootAccount = {
                    Sid: `RootAccount-${businessID}`,
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${cloudId}:root`,
                    },
                    Action: ['s3:GetObject', 's3:PutObject'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`],
                };
                statement.push(rootAccount);
                const newPolicy = { ...policyJson };
                newPolicy.Statement = statement;
                const newParams = {
                    Bucket: `${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
                    Policy: JSON.stringify(newPolicy),
                };
                await s3.putBucketPolicy(newParams);
                // Same for DLQ
                const dlqParams = {
                    Bucket: `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`,
                };
                const dlqPolicy = await s3.getBucketPolicy(dlqParams);
                const dlqPolicyJson = JSON.parse(dlqPolicy.Policy);
                const dlqStatement = dlqPolicyJson.Statement;
                const rootAccountForDLQ = {
                    Sid: `RootAccount-${businessID}`,
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${cloudId}:root`,
                    },
                    Action: ['s3:GetObject'], // Only need read for DLQ
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`],
                };
                dlqStatement.push(rootAccountForDLQ);
                const newDLQPolicy = { ...dlqPolicyJson };
                newDLQPolicy.Statement = dlqStatement;
                const newDLQParams = {
                    Bucket: `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`,
                    Policy: JSON.stringify(newDLQPolicy),
                };
                await s3.putBucketPolicy(newDLQParams);
            } catch (e) {
                if (e?.Code === 'MalformedPolicy') {
                    throw new BadRequestException(`CloudId: ${cloudId} is invalid`);
                } else {
                    throw e;
                }
            }
        }
    }
}

export class AgentAccessInformation extends IAMAccessCredentials {
    /**
     * Hosting platform of SaaS application
     *
     */
    @Matches(
        `^${Object.values(SupportedAgentHostingPlatforms)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsNotEmpty()
    @ApiProperty({ enum: SupportedAgentHostingPlatforms, isArray: false, example: 'eks' })
    public hostingPlatform: SupportedAgentHostingPlatforms;

    constructor(agentAccessInformation: AgentAccessInformation) {
        super({ ...agentAccessInformation });
        if (agentAccessInformation) {
            const { iamRoleArn, externalId, hostingPlatform } = agentAccessInformation;
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.hostingPlatform = hostingPlatform;
        }
    }

    public static transformer(agentAccessInformation: AgentAccessInformation, influxPoint: Point): Point {
        if (agentAccessInformation) {
            const { iamRoleArn, externalId, hostingPlatform } = agentAccessInformation;

            influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) {
                influxPoint.tag('externalId', externalId);
            }
            if (hostingPlatform) {
                influxPoint.tag('hostingPlatform', hostingPlatform.toLowerCase());
            } else {
                influxPoint.tag('hostingPlatform', '');
            }

            return influxPoint;
        }
        return influxPoint;
    }

    public static dbModelToEntity({ iamRoleArn, externalId = '', hostingPlatform }: { [x: string]: any }) {
        let parsedHostingPlatform;
        if (hostingPlatform) {
            parsedHostingPlatform = hostingPlatform.toLowerCase();
        }
        return new AgentAccessInformation({
            iamRoleArn,
            externalId,
            hostingPlatform: parsedHostingPlatform,
        });
    }
}

