import { Tag } from '@aws-sdk/client-ec2';
import { randomUUID } from 'crypto';
import EventEmitter from 'events';
import { AuditService } from '../../audit/audit.service';
import { AuditScope } from '../../audit/entities/audit.interface';
import { InfluxService } from '../../influx/influx.service';
import { MeasurementFormat } from './measurement.interface';

const eventEmitter = new EventEmitter();
export class StandardMeasurementEntity implements MeasurementFormat {
    public timeStamp?: string;
    public dimensionId?: string;
    public businessID: string;
    public applicationId?: string;
    public serviceId?: string;
    public recordValue: number;
    public metadata: Record<string, string>;
    public _measurement: string;
    public static allowedTags = ['paigoApplicationId', 'paigoServiceId', 'paigoDimensionId'];

    constructor(measurement: MeasurementFormat) {
        if (measurement.timeStamp) {
            this.timeStamp = measurement.timeStamp;
        } else {
            this.timeStamp = new Date().toISOString();
        }
        this.dimensionId = measurement.dimensionId;
        this.applicationId = measurement.applicationId;
        this.serviceId = measurement.serviceId;
        this.recordValue = measurement.recordValue;
        this.metadata = measurement.metadata;
        this.businessID = measurement.businessID;
        this._measurement = measurement._measurement;
    }
    static publish(publishRequest: MeasurementFormat) {
        eventEmitter.emit('standardMeasurements', publishRequest);
        return {
            message: 'published',
            id: randomUUID(),
            data: [publishRequest],
        };
    }
    static subscribe(influxService: InfluxService) {
        eventEmitter.on('standardMeasurements', async (measurementFormat: MeasurementFormat) => {
            const point = MeasurementFormat.getPointForm(measurementFormat, influxService);
            try {
                await influxService.loadPoints(`${process.env.STAGE}-usage-data`, `paigo`, [point]);
            } catch (err) {
                AuditService.publishEvent({
                    data: [{ err }],
                    message: 'Failed to index Measurement',
                    topic: AuditScope.ERROR,
                });
            }
        });
    }
    static awsTagKeyReducer(Tags: Tag[]) {
        if (Tags) {
            return Tags.reduce((acc, { Key, Value }): any => {
                if (StandardMeasurementEntity.allowedTags.includes(Key)) {
                    acc[Key] = Value;
                }
                return acc;
            }, {});
        } else {
            return {};
        }
    }
}

import { Body, Controller, Logger, Post, Req, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { ApiBadRequestResponse, ApiCreatedResponse, ApiOperation, ApiTags } from '@nestjs/swagger';
import { BasicResponseDTO } from '../basicResponseDTO';
import { CreateUsageDto } from './dto/create-usage.dto';
import { UsageService } from './usage.service';
import { Request } from 'express';
import { DbMeasuredusageDto } from './dto/dbmeasuredUsage.dto';
import { LogGaurd } from '../authz/logGaurd';

@ApiTags('Usage')
@Controller('usage')
export class UsageController {
    private static readonly logger = new Logger(UsageController.name);
    constructor(private readonly usageService: UsageService) {}

    /**
     * Collect usage data by API-based method.
     * See <a href="https://docs.paigo.tech/measure-usage-and-collect-data/measure-and-collect-usage-data-at-production-scale">Measure and Collect Usage Data At Production Scale</a>
     * for full documentation on Paigo <b>Usage Measurement and Collection</b>.
     * @param createUsageDto
     * @param request
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'OK',
        type: BasicResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Collect usage data' })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() createUsageDto: CreateUsageDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.usageService.create({ ...createUsageDto, businessID });
    }

    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    dbUsage(@Body() createUsageDto) {
        // Custom validator for DB usage, on failure push to DLQ for manual processing

        UsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto;
        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        if (s3Key) {
            const [businessID] = s3Key.split('/');
            const parsed = JSON.parse(message);
            const input = { ...parsed, businessID };
            return this.usageService.create(input);
        } else {
            // TODO push to DLQ
            return '';
        }
    }
}
