async function bootstrap() {
    const app = await NestFactory.create(AppModule);
    app.useGlobalPipes(new ValidationPipe({ whitelist: true }));
    const config = new DocumentBuilder()
        .setTitle('Paigo API')
        // .setDescription('For user documentation of the platform, please visit https://docs.paigo.tech.')
        .setDescription(
            `
For developer documentation of the platform, please visit https://docs.paigo.tech.

## Authentication
Paigo API supports **bearer token** as the authentication method.
Steps to set up authentication:
1. Sign up with Paigo platform and get **client id** and **client secret**.
2. Make a POST request to the auth endpoint \`https://dev-joaofx7i.us.auth0.com/oauth/token\` with the following body:
\`\`\`json
{
        audience: 'https://qnonyh1pc7.execute-api.us-east-1.amazonaws.com',
        grant_type: 'client_credentials',
        client_id: <your client id>,
        client_secret: <your client secret>
}
\`\`\`
3. Use the access token in the response to make requests to the Paigo API. Here is an example of the response:
\`\`\`json
{
        data: {
            access_token: <your access token>,
            expires_in: 86400,
            token_type: 'Bearer'
        }
}
\`\`\`
4. To use Paigo API, add in the header of your request:
\`\`\`json
{
        Authorization: "Bearer <your access token>"
}
\`\`\`

## API Endpoints
Paigo API has the following endpoints:
- Sandbox Environment API: \`https://api.int.paigo.tech\`

- Sandbox Environment API: \`https://api.int.paigo.tech\`
- Product Environment API: \`https://api.prod.paigo.tech\`
        `
        )
        .setVersion('v1.10')
        .addTag('Usage', 'Measure and collect usage data.')
        .addTag('Dimensions', 'Manage dimensions in Paigo.')
        .addTag('Offerings', 'Manage offerings in Paigo.')
        .addTag('Customers', 'Manage customers in Paigo.')
        .addTag('Services', 'Manage services in Paigo.')
        .addTag('Measurements', 'Manage measurements in Paigo.')
        .addServer('https://api.int.paigo.tech', 'Sandbox Environment API')
        .addServer('https://api.prod.paigo.tech', 'Product Environment API')
        .addBearerAuth(
            {
                type: 'oauth2',
                scheme: 'bearer',
                bearerFormat: 'JWT',
                in: 'Header',
                description: 'Use bearer token to authenticate `Bearer <your access token>`',
            },
