export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The datastore platform used when a customer does not specify one.
 */
export const DEFAULT_DATASTORE_PLATFORM = SupportedDatastores.s3;

/**
 * The region used for datastore based measurements when neither the customer nor the
 * environment provides one.
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for the connectors which ingest data dropped by a client
 * into a Paigo owned datastore.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as an S3 connector.
 *
 * For `s3` the customer only provides the AWS account which will be writing usage records.
 * Paigo generates and returns everything which is needed to start dropping records:
 * an IAM role (`iamRoleArn`) which can be assumed by that account with the generated `externalId`,
 * the `ingestion` location where records are dropped and the `dlq` location where records which
 * could not be processed are written.
 * */
export class DatastoreAccessInformation {
    private static readonly logger = new Logger(DatastoreAccessInformation.name);

    /**
     * The datastore platform which Paigo hosts for the customer. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        example: 's3',
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the customer cloud account which writes the usage records. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * The IAM role generated by Paigo which the account identified by `accountId` can assume
     * in order to write usage records. Generated by Paigo, any provided value is ignored.
     * <br><br>
     * Example `"arn:aws:iam::647662420899:role/datastore-myBusiness-de388932-a7e1-11ed-afa1-0242ac120002"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * The external ID which must be used when assuming `iamRoleArn`. Generated by Paigo,
     * any provided value is ignored.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * The location where usage records must be dropped.
     * <br><br>
     * Example `"s3://paigo-usage-record-dump-bucket/myBusiness"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * The location where usage records which could not be processed are written.
     * <br><br>
     * Example `"s3://paigo-usage-record-dlq-bucket/myBusiness"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    /**
     * The region of the datastore. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation & { [x: string]: any }) {
        if (datastoreAccessInformation) {
            const {
                platform,
                accountId,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                region,
                businessID,
                measurementId,
            } = datastoreAccessInformation;
            this.platform = (platform ? platform : DEFAULT_DATASTORE_PLATFORM) as SupportedDatastores;
            this.accountId = accountId;
            this.region = region ? region : DatastoreAccessInformation.defaultRegion();
            this.businessID = businessID;
            this.measurementId = measurementId;
            if (iamRoleArn) {
                this.iamRoleArn = iamRoleArn;
            }
            if (externalId) {
                this.externalId = externalId;
            }
            const resolvedIngestion = ingestion
                ? ingestion
                : DatastoreAccessInformation.ingestionLocation(businessID);
            const resolvedDlq = dlq ? dlq : DatastoreAccessInformation.dlqLocation(businessID);
            if (resolvedIngestion) {
                this.ingestion = resolvedIngestion;
            }
            if (resolvedDlq) {
                this.dlq = resolvedDlq;
            }
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, iamRoleArn, externalId, ingestion, dlq, region } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform.toLowerCase());
            if (accountId) influxPoint.tag('accountId', accountId);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
            if (region) influxPoint.tag('region', region);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        region,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform: platform ? platform.toLowerCase() : platform,
            accountId,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            region,
            businessID,
            measurementId,
        } as DatastoreAccessInformation);
    }

    /**
     * The name of the IAM role, and of its policy, which is provisioned for a datastore based measurement.
     */
    public static roleName(businessID: string, measurementId: string) {
        return `datastore-${businessID}-${measurementId}`;
    }

    public static policyName(businessID: string, measurementId: string) {
        return `${DatastoreAccessInformation.roleName(businessID, measurementId)}-policy`;
    }

    public static ingestionLocation(businessID: string) {
        if (!businessID || !process.env.DB_MEASUREMENT_BUCKET_NAME) {
            return undefined;
        }
        return `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`;
    }

    public static dlqLocation(businessID: string) {
        if (!businessID || !process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME) {
            return undefined;
        }
        return `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`;
    }

    /**
     * Provisions the access which a customer needs in order to drop usage records into the
     * Paigo owned datastore.
     *
     * A uniquely named IAM role, scoped to the ingestion and DLQ prefixes of the business, is created.
     * The role can only be assumed by the customer account (`accountId`) and only when the freshly
     * generated external ID is provided.
     *
     * @param dbAccessInformation the customer provided datastore configuration, it is enriched in place
     * @param context the businessID/measurementId of the measurement being created, they may also be
     * carried by `dbAccessInformation`. A plain string is treated as the measurementId.
     * @returns the enriched configuration, which is returned to, and stored for, the customer
     */
    public static async setupAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context?: string | { businessID?: string; measurementId?: string }
    ): Promise<DatastoreAccessInformation> {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { businessID, measurementId } = DatastoreAccessInformation.resolveContext(dbAccessInformation, context);
        const platform = dbAccessInformation.platform ? dbAccessInformation.platform : DEFAULT_DATASTORE_PLATFORM;
        if (platform.toLowerCase() !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        const { accountId } = dbAccessInformation;
        if (!accountId) {
            throw new BadRequestException('accountId is required for datastore based measurements');
        }
        const roleName = DatastoreAccessInformation.roleName(businessID, measurementId);
        const externalId = randomUUID();

        DatastoreAccessInformation.logger.log(`Provisioning datastore access with the IAM role: ${roleName}`);
        const iam = DatastoreAccessInformation.getIAMClient(dbAccessInformation.region);
        try {
            const { Role } = await iam.createRole({
                RoleName: roleName,
                Description: `Paigo usage record ingestion for businessID: ${businessID}`,
                AssumeRolePolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.trustPolicyDocument(accountId, externalId)
                ),
                Tags: [
                    { Key: 'businessID', Value: `${businessID}` },
                    { Key: 'measurementId', Value: `${measurementId}` },
                ],
            });
            await iam.putRolePolicy({
                RoleName: roleName,
                PolicyName: DatastoreAccessInformation.policyName(businessID, measurementId),
                PolicyDocument: JSON.stringify(DatastoreAccessInformation.accessPolicyDocument(businessID)),
            });

            dbAccessInformation.platform = platform;
            dbAccessInformation.businessID = businessID;
            dbAccessInformation.measurementId = measurementId;
            dbAccessInformation.iamRoleArn = Role?.Arn
                ? Role.Arn
                : DatastoreAccessInformation.fallbackRoleArn(roleName);
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.ingestion = DatastoreAccessInformation.ingestionLocation(businessID);
            dbAccessInformation.dlq = DatastoreAccessInformation.dlqLocation(businessID);
            dbAccessInformation.region = dbAccessInformation.region
                ? dbAccessInformation.region
                : DatastoreAccessInformation.defaultRegion();

            return dbAccessInformation;
        } catch (error) {
            throw DatastoreAccessInformation.toHttpError(error, accountId);
        }
    }

    /**
     * Updates the trust of the IAM role which was provisioned for a datastore based measurement.
     * The role itself, and its external ID, are preserved so that a customer only has to update
     * the account which assumes the role.
     *
     * @param dbAccessInformation the stored configuration merged with the update
     * @param context the businessID/measurementId of the measurement being updated
     * @returns the configuration which is returned to, and stored for, the customer
     */
    public static async updateAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context?: string | { businessID?: string; measurementId?: string }
    ): Promise<DatastoreAccessInformation> {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { businessID, measurementId } = DatastoreAccessInformation.resolveContext(dbAccessInformation, context);
        const platform = dbAccessInformation.platform ? dbAccessInformation.platform : DEFAULT_DATASTORE_PLATFORM;
        if (platform.toLowerCase() !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        const { accountId, iamRoleArn } = dbAccessInformation;
        if (!accountId) {
            throw new BadRequestException('accountId is required for datastore based measurements');
        }
        // The role and the external ID are never regenerated, only the account which trusts them changes
        const roleName = DatastoreAccessInformation.roleNameFromArn(iamRoleArn)
            ? DatastoreAccessInformation.roleNameFromArn(iamRoleArn)
            : DatastoreAccessInformation.roleName(businessID, measurementId);
        const externalId = dbAccessInformation.externalId ? dbAccessInformation.externalId : randomUUID();

        DatastoreAccessInformation.logger.log(`Updating the trust of the IAM role: ${roleName}`);
        const iam = DatastoreAccessInformation.getIAMClient(dbAccessInformation.region);
        try {
            await iam.updateAssumeRolePolicy({
                RoleName: roleName,
                PolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.trustPolicyDocument(accountId, externalId)
                ),
            });

            dbAccessInformation.platform = platform;
            dbAccessInformation.businessID = businessID;
            dbAccessInformation.measurementId = measurementId;
            dbAccessInformation.iamRoleArn = iamRoleArn
                ? iamRoleArn
                : DatastoreAccessInformation.fallbackRoleArn(roleName);
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.ingestion = DatastoreAccessInformation.ingestionLocation(businessID);
            dbAccessInformation.dlq = DatastoreAccessInformation.dlqLocation(businessID);
            dbAccessInformation.region = dbAccessInformation.region
                ? dbAccessInformation.region
                : DatastoreAccessInformation.defaultRegion();

            return dbAccessInformation;
        } catch (error) {
            throw DatastoreAccessInformation.toHttpError(error, accountId);
        }
    }

    /**
     * The policy which allows the customer account to assume the generated role, but only when the
     * generated external ID is provided.
     */
    public static trustPolicyDocument(accountId: string, externalId: string) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'PaigoDatastoreAccountTrust',
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    /**
     * The policy which scopes the generated role to the ingestion and DLQ prefixes of a single business.
     */
    public static accessPolicyDocument(businessID: string) {
        const ingestionBucket = `${process.env.DB_MEASUREMENT_BUCKET_NAME}`;
        const dlqBucket = `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'PaigoDatastoreObjectAccess',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload', 's3:ListMultipartUploadParts'],
                    Resource: [
                        `arn:aws:s3:::${ingestionBucket}/${businessID}/*`,
                        `arn:aws:s3:::${dlqBucket}/${businessID}/*`,
                    ],
                },
                {
                    Sid: 'PaigoDatastoreBucketAccess',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket', 's3:GetBucketLocation'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}`, `arn:aws:s3:::${dlqBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${businessID}/*`],
                        },
                    },
                },
            ],
        };
    }

    public static roleNameFromArn(iamRoleArn?: string) {
        if (!iamRoleArn) {
            return undefined;
        }
        const [roleName] = iamRoleArn.split('/').slice(-1);
        return roleName ? roleName : undefined;
    }

    private static defaultRegion() {
        return process.env.AWS_REGION ? process.env.AWS_REGION : DEFAULT_DATASTORE_REGION;
    }

    private static getIAMClient(region?: string) {
        return new IAM({ region: region ? region : DatastoreAccessInformation.defaultRegion() });
    }

    private static fallbackRoleArn(roleName: string) {
        return `arn:aws:iam::${process.env.PAIGO_AWS_ACCOUNT_ID ? process.env.PAIGO_AWS_ACCOUNT_ID : ''}:role/${roleName}`;
    }

    private static resolveContext(
        dbAccessInformation: DatastoreAccessInformation,
        context?: string | { businessID?: string; measurementId?: string }
    ) {
        const overrides = typeof context === 'string' ? { measurementId: context } : context;
        return {
            businessID: overrides?.businessID ? overrides.businessID : dbAccessInformation.businessID,
            measurementId: overrides?.measurementId ? overrides.measurementId : dbAccessInformation.measurementId,
        };
    }

    private static toHttpError(error, accountId: string) {
        const code = error?.name ? error.name : error?.Code;
        DatastoreAccessInformation.logger.error('Failed to provision datastore access', error);
        if (code === 'MalformedPolicyDocument' || code === 'MalformedPolicyDocumentException' || code === 'MalformedPolicy') {
            return new BadRequestException(`accountId: ${accountId} is invalid`);
        }
        if (code === 'EntityAlreadyExists' || code === 'EntityAlreadyExistsException') {
            return new ConflictException('Access for this datastore measurement has already been provisioned');
        }
        return error;
    }
}

