import { Tag } from '@aws-sdk/client-ec2';
import { S3 } from '@aws-sdk/client-s3';
import { Logger } from '@nestjs/common';
import { randomUUID } from 'crypto';
import EventEmitter from 'events';
import { AuditService } from '../../audit/audit.service';
import { AuditScope } from '../../audit/entities/audit.interface';
import { InfluxService } from '../../influx/influx.service';
import { MeasurementFormat } from './measurement.interface';

const eventEmitter = new EventEmitter();

/**
 * A measurement which could not be turned into a standard measurement.
 * The failed input is written to the DLQ, mirroring the key of the source which delivered it,
 * so that it can be inspected and reprocessed.
 */
export type MeasurementFailure = {
    /**
     * The input which could not be processed.
     */
    failedInput?: unknown;
    /**
     * The key of the source object which delivered the failed input.
     * It may be a full uri, `s3://bucket/key`, or a key which is already relative to its bucket.
