    static async publishFailureToDLQ(
        failureOrFailedInput: MeasurementFailure | unknown,
        sourceKey?: string,
        error?: unknown
    ): Promise<MeasurementFailureResponse> {
        const failure: MeasurementFailure =
            sourceKey =<REDACTED>
                ? ((failureOrFailedInput ? failureOrFailedInput : {}) as MeasurementFailure)
                : { failedInput: failureOrFailedInput, sourceKey, error };

        const source = failure.sourceKey ? failure.sourceKey : failure.s3Key;
        const relativeKey = StandardMeasurementEntity.relativeSourceKey(source);
        const Bucket = failure.bucket ? failure.bucket : `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
        const Key = `${relativeKey}${StandardMeasurementEntity.DLQ_KEY_SUFFIX}`;
        const businessID = failure.businessID
            ? failure.businessID
            : StandardMeasurementEntity.businessIDFromSourceKey(source);
        const failureError = failure.error as Error;

        const body = {
            failedInput: failure.failedInput,
            metadata: {
                businessID,
                sourceKey: source,
                dlqBucket: Bucket,
                dlqKey: Key,
                source: failure.source,
                error: failureError?.message ? failureError.message : failure.error,
                errorName: failureError?.name,
                processedAt: new Date().toISOString(),
            },
        };

        StandardMeasurementEntity.logger.warn(`Publishing a failed measurement to the DLQ: ${Bucket}/${Key}`);
        const s3 = new S3({
            region: process.env.AWS_REGION ? process.env.AWS_REGION : 'us-east-1',
        });
        await s3.putObject({
            Bucket,
            Key,
            Body: JSON.stringify(body, null, 2),
        });
        AuditService.publishEvent({
            data: [body],
            message: 'Published a failed measurement to the DLQ',
            topic: AuditScope.ERROR,
        });

        return { message: 'Published failure to DLQ', bucket: Bucket, key: Key };
    }

    /**
     * Turns the key of a source object into a key which is relative to its bucket, so that it can be
     * mirrored into another bucket. Keys which are already relative are returned untouched.
     */
    static relativeSourceKey(sourceKey?: string) {
        if (!sourceKey) {
            return `unprocessable/${randomUUID()}`;
        }
        let key = `${sourceKey}`;
        const uriMatch = key.match(/^s3a?:\/\//i);
        if (uriMatch) {
            // A full uri, s3://bucket/key, carries the bucket as its first segment
            key = key.slice(uriMatch[0].length).split('/').slice(1).join('/');
        }
        key = key.replace(/^\/+/, '');
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        if (ingestionBucket && key.startsWith(`${ingestionBucket}/`)) {
            key = key.slice(`${ingestionBucket}/`.length);
        }
        return key ? key : `unprocessable/${randomUUID()}`;
    }

    /**
     * The business a source object belongs to is the first segment of its key.
     */
    static businessIDFromSourceKey(sourceKey?: string) {
        const [businessID] = StandardMeasurementEntity.relativeSourceKey(sourceKey).split('/');
        return businessID;
    }
}

