import { Body, Controller, Logger, Post, Req, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { ApiBadRequestResponse, ApiCreatedResponse, ApiOperation, ApiTags } from '@nestjs/swagger';
import { BasicResponseDTO } from '../basicResponseDTO';
import { CreateUsageDto } from './dto/create-usage.dto';
import { UsageService } from './usage.service';
import { Request } from 'express';
import { DbMeasuredusageDto } from './dto/dbmeasuredUsage.dto';
import { LogGaurd } from '../authz/logGaurd';
import { StandardMeasurementEntity } from '../measurement-config/entities/standardMeasurement.entity';

@ApiTags('Usage')
@Controller('usage')
export class UsageController {
    private static readonly logger = new Logger(UsageController.name);
    constructor(private readonly usageService: UsageService) {}

    /**
     * Collect usage data by API-based method.
     * See <a href="https://docs.paigo.tech/measure-usage-and-collect-data/measure-and-collect-usage-data-at-production-scale">Measure and Collect Usage Data At Production Scale</a>
     * for full documentation on Paigo <b>Usage Measurement and Collection</b>.
     * @param createUsageDto
     * @param request
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'OK',
        type: BasicResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Collect usage data' })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() createUsageDto: CreateUsageDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.usageService.create({ ...createUsageDto, businessID });
    }

    /**
     * Collect usage data by datastore-based method.
     *
     * This endpoint is only called by the internal connector which reads the records a customer drops
     * into the Paigo owned datastore. Every delivery carries a single standard usage record as
     * `message` and the key of the object it was read from as `s3Key`, whose first segment is the
     * business the record belongs to.
     *
     * A record which cannot be processed is never retried, it is published to the DLQ of the
     * measurement so that it can be inspected and reprocessed.
     */
    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    async dbUsage(@Body() createUsageDto) {
        UsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto ? (createUsageDto as DbMeasuredusageDto) : ({} as DbMeasuredusageDto);
        try {
            // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
            if (!s3Key) {
                throw new Error('No s3Key was delivered with the usage record');
            }
            const businessID = StandardMeasurementEntity.businessIDFromSourceKey(s3Key);
            const parsed = typeof message === 'string' ? JSON.parse(message) : message;
            if (!parsed || typeof parsed !== 'object') {
                throw new Error('The delivered usage record is not a usage record');
            }
            return await this.usageService.create({ ...parsed, businessID });
        } catch (error) {
            UsageController.logger.error(`Failed to process the usage record read from ${s3Key}`, error);
            return StandardMeasurementEntity.publishFailureToDLQ({
                failedInput: createUsageDto,
                sourceKey: s3Key,
                error,
                source: `${UsageController.name}.dbUsage`,
            });
        }
    }
}

export { UsageController as PublicAPIUsageController };

/**
 * The private API exposes the same usage collection as the public API, the internal connector of a
 * datastore based measurement delivers its records to it.
 */
@ApiTags('Usage')
@Controller('usage')
export class PrivateAPIUsageController extends UsageController {}

import { CreateUsageDto } from './create-usage.dto';

/**
 * The delivery of the connector which reads the usage records a customer drops into the Paigo owned
 * datastore.
 */
export class DbMeasuredusageDto {
    /**
     * A single standard usage record, delivered as the JSON string it was read as.
     */
    message: string | CreateUsageDto;

    /**
     * The key of the object the record was read from, its first segment is the business the record
     * belongs to.
     * <br><br>
     * Example `"myBusiness/topics/usage/partition=0/usage+0+0000000001.json"`
     */
    s3Key: string;
}

