describe('DatastoreAccessInformation', () => {
    const iamMock = mockClient(IAMClient);
    const businessID = 'fakeBusiness';
    const measurementId = 'fakeMeasurement';
    const accountId = '623673123435';
    const iamRoleArn = `arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}`;

    beforeEach(() => {
        iamMock.reset();
        iamMock.on(CreateRoleCommand).resolves({ Role: { Arn: iamRoleArn } as never });
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        process.env.AWS_REGION = 'us-east-1';
    });

    const datastoreEntity = (measurementConfiguration) =>
        new MeasurementConfigEntity({
            measurementId,
            measurementMode: measurementMode.datastoreBased,
            measurementConfiguration,
            businessID,
            subject: 'fakeSubject',
            measurementName: 'fakeMeasurementName',
        } as MeasurementConfigEntity);

    it('should default the platform and the region of a datastore measurement', () => {
        const { measurementConfiguration } = datastoreEntity({ accountId });

        expect(measurementConfiguration).toBeInstanceOf(DatastoreAccessInformation);
        expect(measurementConfiguration).toEqual(
            expect.objectContaining({ platform: SupportedDatastores.s3, accountId, region: 'us-east-1' })
        );
    });

    it('should provision a uniquely named IAM role which trusts the account of the customer', async () => {
        const configuration = await DatastoreAccessInformation.setupAccess({
            accountId,
            businessID,
            measurementId,
        } as DatastoreAccessInformation);

        const [createRole] = iamMock.commandCalls(CreateRoleCommand);
        expect(createRole.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);

        const trustPolicy = JSON.parse(`${createRole.args[0].input.AssumeRolePolicyDocument}`);
        const [trustStatement] = trustPolicy.Statement;
        expect(trustStatement.Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
        expect(trustStatement.Condition.StringEquals['sts:ExternalId']).toEqual(configuration.externalId);
        expect(configuration.externalId).toEqual(expect.any(String));
    });

    it('should scope the policy of the provisioned role to the prefixes of the business', async () => {
        await DatastoreAccessInformation.setupAccess({
            accountId,
            businessID,
            measurementId,
        } as DatastoreAccessInformation);

        const [putRolePolicy] = iamMock.commandCalls(PutRolePolicyCommand);
        expect(putRolePolicy.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        expect(putRolePolicy.args[0].input.PolicyName).toEqual(`datastore-${businessID}-${measurementId}-policy`);

        const policy = JSON.parse(`${putRolePolicy.args[0].input.PolicyDocument}`);
        const [objectAccess] = policy.Statement;
        expect(objectAccess.Resource).toEqual([
            `arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`,
            `arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`,
        ]);
    });

    it('should return the generated access information of a datastore measurement', async () => {
        const entity = datastoreEntity({ accountId });
        await MeasurementConfigEntity.setupAccessIfRequired(entity);

        expect(entity.measurementConfiguration).toEqual(
            expect.objectContaining({
                platform: SupportedDatastores.s3,
                accountId,
                iamRoleArn,
                externalId: expect.any(String),
                ingestion: `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`,
                dlq: `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`,
                region: 'us-east-1',
            })
        );
    });

    it('should reject a datastore measurement without an account', async () => {
        await expect(
            DatastoreAccessInformation.setupAccess({ businessID, measurementId } as DatastoreAccessInformation)
        ).rejects.toThrow('accountId is required for datastore based measurements');
        expect(iamMock.commandCalls(CreateRoleCommand)).toHaveLength(0);
    });

    it('should update the trust of the role while preserving the role and its external ID', async () => {
        const externalId = 'aFreshExternalId';
        const updatedAccountId = '999999999999';

        const configuration = await DatastoreAccessInformation.updateAccess({
            platform: SupportedDatastores.s3,
            accountId: updatedAccountId,
            iamRoleArn,
            externalId,
            businessID,
            measurementId,
        } as DatastoreAccessInformation);

        const [updateTrust] = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
        expect(updateTrust.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const [trustStatement] = JSON.parse(`${updateTrust.args[0].input.PolicyDocument}`).Statement;
        expect(trustStatement.Principal.AWS).toEqual(`arn:aws:iam::${updatedAccountId}:root`);
        expect(trustStatement.Condition.StringEquals['sts:ExternalId']).toEqual(externalId);

        expect(iamMock.commandCalls(CreateRoleCommand)).toHaveLength(0);
        expect(configuration).toEqual(expect.objectContaining({ iamRoleArn, externalId }));
    });

    it('should read the stored access information of a datastore measurement back', () => {
        const entity = MeasurementConfigEntity.dbModelToEntity({
