            externalId: 'aStoredExternalId',
            ingestion: `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`,
            dlq: `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`,
            region: 'us-east-1',
        });

        expect(entity.measurementConfiguration).toEqual(
            expect.objectContaining({
                platform: SupportedDatastores.s3,
                accountId,
                iamRoleArn,
                externalId: 'aStoredExternalId',
                region: 'us-east-1',
            })
        );
    });

    it('should store the access information of a datastore measurement', async () => {
        const entity = datastoreEntity({ accountId });
        await MeasurementConfigEntity.setupAccessIfRequired(entity);

        const tag = jest.fn();
        const stringField = jest.fn();
        MeasurementConfigEntity.transformer(entity, {
