    const s3Mock = mockClient(S3Client);
    const mockCreate = jest.fn();
    let controller: PrivateAPIUsageController;
    const businessID = 'fakeBusiness';
    const usageRecord = {
        dimensionId: 'fakeDimension',
        serviceId: 'fakeService',
        recordValue: 12,
        timeStamp: '2023-02-21T00:00:00.000Z',
        metadata: { region: 'us-east-1' },
    };

    beforeEach(async () => {
        s3Mock.reset();
        mockCreate.mockReset();
        mockCreate.mockResolvedValue({ message: 'Measurement created' });
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        process.env.AWS_REGION = 'us-east-1';

        const module: TestingModule = await Test.createTestingModule({
            controllers: [PrivateAPIUsageController],
        })
            .useMocker((token) => {
                if (token === UsageService) {
                    return { create: mockCreate };
                }
            })
            .compile();

        controller = module.get<PrivateAPIUsageController>(PrivateAPIUsageController);
    });

    it('should measure a delivered record for the business the source key belongs to', async () => {
        const response = await controller.dbUsage({
            message: JSON.stringify(usageRecord),
            s3Key: `${businessID}/topics/usage/partition=0/usage+0+0000000001.json`,
        });

        expect(mockCreate).toHaveBeenCalledWith({ ...usageRecord, businessID });
        expect(response).toEqual({ message: 'Measurement created' });
        expect(s3Mock.commandCalls(PutObjectCommand)).toHaveLength(0);
    });

    it('should publish a malformed record to the DLQ, mirroring the key of its source', async () => {
        const s3Key = `${businessID}/topics/usage/partition=0/usage+0+0000000001.json`;
        const message = 'notAUsageRecord';

        await controller.dbUsage({ message, s3Key });

        expect(mockCreate).not.toHaveBeenCalled();
        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Bucket).toEqual(process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME);
        expect(putObject.args[0].input.Key).toEqual(`${s3Key}.message.text`);

        const published = JSON.parse(`${putObject.args[0].input.Body}`);
        expect(published.failedInput).toEqual({ message, s3Key });
        expect(published.metadata).toEqual(
            expect.objectContaining({
                businessID,
                sourceKey: s3Key,
                dlqKey: `${s3Key}.message.text`,
                error: expect.any(String),
                processedAt: expect.any(String),
            })
        );
    });

    it('should mirror the key of a source which is delivered as a full uri', async () => {
        const key = `${businessID}/topics/usage/partition=0/usage+0+0000000002.json`;

        await controller.dbUsage({
            message: '{ "recordValue": ',
            s3Key: `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${key}`,
        });

        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Key).toEqual(`${key}.message.text`);
    });

    it('should publish a delivery without a source key to the DLQ', async () => {
        await controller.dbUsage({ message: JSON.stringify(usageRecord) });

        expect(mockCreate).not.toHaveBeenCalled();
        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Bucket).toEqual(process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME);
        expect(`${putObject.args[0].input.Key}`.endsWith('.message.text')).toEqual(true);
    });
});

