@UseGuards(LogGaurd, AuthGuard('jwt'))
@Post('db')
dbUsage(@Body() createUsageDto) {
    UsageController.logger.log('Starting DB Usage Endpoint execution');

    const { message, s3Key } = createUsageDto
        ? (createUsageDto as DbMeasuredusageDto)
        : ({} as DbMeasuredusageDto);
    try {
        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        if (!s3Key) {
            throw new Error('No s3Key was delivered with the usage record');
        }
        const businessID = StandardMeasurementEntity.businessIDFromSourceKey(s3Key);
        const parsed = typeof message === 'string' ? JSON.parse(message) : message;
        if (!parsed || typeof parsed !== 'object') {
            throw new Error('The delivered usage record is not a usage record');
        }
        return this.usageService.create({ ...parsed, businessID });
    } catch (error) {
        // A record which could not be processed is never retried, it is published to the DLQ
        UsageController.logger.error(`Failed to process the usage record read from ${s3Key}`, error);
        return StandardMeasurementEntity.publishFailureToDLQ({
            failedInput: createUsageDto,
            sourceKey: s3Key,
            error,
            source: `${this.constructor.name}.dbUsage`,
        });
    }
}

